        if offset == len(data) - 1 and data[offset] == 128:
            return result
        messages += 1
        if messages > 256:
            raise _sg_h264clock_GridError('h264_sei_message_limit')
        values = []
        for _ in range(2):
            value = 0
            while offset < len(data) and data[offset] == 255:
                value += 255
                offset += 1
            if offset >= len(data):
                raise _sg_h264clock_GridError('h264_sei_truncated')
