    if nal_type == 5:
        reader.bit()
        reader.bit()
        return False
    if not nal_ref_idc:
        return False
    if not reader.bit():
        return False
    for _ in range(64):
        operation = reader.ue()
        if operation == 0:
            return False
        if operation in (1, 3):
            reader.ue()
        if operation == 2:
            reader.ue()
        if operation in (3, 6):
            reader.ue()
        if operation == 4:
            reader.ue()
        if operation == 5:
            return True
        if operation > 6:
            raise _sg_h264clock_GridError('h264_memory_management_operation_invalid')
    raise _sg_h264clock_GridError('h264_memory_management_operation_limit')

