def _sg_stream_validate_media_output(stats):
    """Reject a nominally successful stop when output lacks A/V coverage."""
    if not stats.get('video_output_frames'):
        raise _sg_stream_GridError('no_playable_grid_video')
    if not stats.get('audio_output_access_units'):
        raise _sg_stream_GridError('no_playable_grid_audio')
    if stats.get('expected_grid_height') and (not stats.get('grid_quality_verified')):
        raise _sg_stream_GridError('grid_quality_resolution_unverified')
    span_status = stats.get('av_track_span_status')
    if span_status == 'incomplete':
        raise _sg_stream_GridError('media_track_coverage_incomplete')
    if span_status != 'consistent':
        raise _sg_stream_GridError('media_track_coverage_unverified')

class _sg_stream_BoundedBuffer:

    def __init__(self, capacity, timeout):
        if type(capacity) is not int or not 188 <= capacity <= 16 << 20 or type(timeout) not in (int, float) or (not 0 < timeout < _sg_stream_math.inf):
            raise ValueError('buffer configuration invalid')
        self.capacity = capacity
        self.timeout = timeout
        self.data = bytearray()
        self.condition = _sg_stream_threading.Condition()
        self.eof = False
        self.cancelled = False
        self.error = None
        self.peak_bytes = 0
        self.last_progress = _sg_stream_time.monotonic()
        self.accepted_bytes = 0
        self.discarded_bytes = 0
        self.unaccepted_bytes = 0

    def put(self, data, *, deadline=None, atomic_unit=1):
        view = memoryview(data)
        if type(atomic_unit) is not int or atomic_unit < 1 or len(view) % atomic_unit:
            raise _sg_stream_GridError('buffer_output_unit_invalid')
        accepted_any = False
        while view:
            with self.condition:
                while not self.cancelled:
                    now = _sg_stream_time.monotonic()
                    if deadline is not None and now >= deadline:
                        self.unaccepted_bytes += len(view)
                        raise _sg_stream_GridError('capture_deadline_reached' if not accepted_any else 'duration_limit_output_incomplete')
                    available = self.capacity - len(self.data)
                    if available >= atomic_unit:
                        break
                    wait_deadline = self.last_progress + self.timeout
                    if deadline is not None:
                        wait_deadline = min(wait_deadline, deadline)
                    remaining = wait_deadline - now
                    if remaining <= 0:
                        if deadline is not None and now >= deadline:
                            self.unaccepted_bytes += len(view)
                            raise _sg_stream_GridError('capture_deadline_reached' if not accepted_any else 'duration_limit_output_incomplete')
                        self.unaccepted_bytes += len(view)
                        raise _sg_stream_GridError('buffer_backpressure_timeout')
                    self.condition.wait(remaining)
                if self.cancelled:
                    self.unaccepted_bytes += len(view)
                    raise _sg_stream_Cancelled('reader_closed')
                n = min(len(view), self.capacity - len(self.data))
                n -= n % atomic_unit
                if n == 0:
                    continue
                self.data.extend(view[:n])
                accepted_any = True
                self.accepted_bytes += n
                self.peak_bytes = max(self.peak_bytes, len(self.data))
                view = view[n:]
                self.last_progress = _sg_stream_time.monotonic()
                self.condition.notify_all()

    def finish(self, error=None):
        with self.condition:
            if self.error is None:
                self.error = error
            self.eof = True
            self.condition.notify_all()

    def wait_ready(self):
        with self.condition:
            self._wait()

    def _wait(self):
        deadline = _sg_stream_time.monotonic() + self.timeout
        while not self.data and (not self.eof) and (not self.cancelled):
            remaining = deadline - _sg_stream_time.monotonic()
            if remaining <= 0:
                raise _sg_stream_StreamError('Grid read timed out')
            self.condition.wait(remaining)
        if not self.data and self.error and (not self.cancelled):
            raise self.error

    def read(self, size):
        if size == 0:
            return b''
        with self.condition:
            self._wait()
            n = min(size if size >= 0 else self.capacity, len(self.data))
            data = bytes(self.data[:n])
            del self.data[:n]
            if n:
                self.last_progress = _sg_stream_time.monotonic()
            self.condition.notify_all()
            return data

    def close(self):
        with self.condition:
            self.cancelled = True
            discarded = len(self.data)
            self.data.clear()
            self.discarded_bytes += discarded
            self.condition.notify_all()
            return discarded

def _sg_stream__receive_attempt(config, network, emit, report, stats):
    session = credentials = sink = None
    primary = None
    try:
        session = _sg_stream_bootstrap(config, report, http_factory=lambda: _sg_stream_HTTP(network.stop))
        stats['bootstrap_bno'] = session.bno
        credentials = _sg_stream_obtain_certificate(network, session, report)
        session.clear_gateway_auth()
        profile = _sg_stream_profile_by_name(config.grid_quality, original_height=config.expected_grid_height if config.grid_quality == 'original' else None)
        stats.update(grid_quality_code=profile.allocation_quality, expected_grid_height=profile.expected_height or 0, grid_quality_verified=0)
        parents, node_key = _sg_stream_discover_parent(network, session.center, credentials, report, quality=profile.allocation_quality, join_quality=profile.join_quality, is_auto=profile.join_is_auto)
        sink = _sg_stream_MediaSink(emit, config.capture_dir, synchronize_startup=True, expected_grid_height=profile.expected_height, grid_quality_code=profile.allocation_quality)
        stats.update(sink.stats)
        sink.stats = stats
        duration = config.duration
        acquisition_deadline = getattr(network, 'acquisition_deadline', None)
        if acquisition_deadline is not None:
            duration = acquisition_deadline - _sg_stream_time.monotonic()
            if duration <= 0:
                raise _sg_stream_GridError('startup_timeout')

        def progress(event):
            if config.startup_retries and event == 'parent_last_media_received':
                sink.update_startup_readiness()
            report(event)
        _sg_stream_receive_media(network, parents, session.bno, node_key, sink, progress, duration, config.max_bytes, rediscover=lambda: _sg_stream_discover_parent(network, session.center, credentials, report, quality=profile.allocation_quality, join_quality=profile.join_quality, is_auto=profile.join_is_auto))
    except BaseException as error:
        primary = error
        raise
    finally:
        try:
            if sink:
                try:
                    sink.close()
                except Exception:
                    if primary is None:
                        raise
                    report('cleanup_failed_after_primary_error')
        finally:
            if credentials:
                credentials.clear()
            if session:
                session.clear()
            config.clear()
            network.close()
    if primary is None and sink is not None:
        _sg_stream_validate_media_output(sink.stats)

def _sg_stream_receive(config, network, emit, report, stats):
    if not config.startup_retries:
        return _sg_stream__receive_attempt(config, network, emit, report, stats)
    try:
        config.validate()
    except BaseException:
        config.clear()
        raise
    return _sg_stream_receive_startup(config, network, emit, report, stats, _sg_stream__receive_attempt, retries=config.startup_retries, window=config.startup_window, capacity=config.startup_memory, attempt_timeout=config.startup_timeout, total_timeout=config.startup_total_timeout)

class _sg_stream_SoopGridReader(_sg_stream_StreamIO):

    def __init__(self, stream, runner=_sg_stream_receive):
        super().__init__()
        self.stream = stream
        self.network = _sg_stream_Network()
        self.buffer = _sg_stream_BoundedBuffer(stream.buffer_size, stream.timeout)
        self.runner = runner
        self.thread = None
        self.stats = {'stream_output_drain_complete': 0, 'stream_output_bytes_drained': 0, 'reader_eof_observed': 0}
        self.stages = _sg_stream_deque(maxlen=128)
        self._close_lock = _sg_stream_threading.Lock()
        self._closing = False
        self.failure_code = None
        self.reader_state = 'initializing'
        self.diagnostics = _sg_stream_Diagnostics(stream.config.diagnostics_dir, self._snapshot)

    def _snapshot(self):
        facts = dict(self.stats)
        with self.buffer.condition:
            facts.update(buffer_used_bytes=len(self.buffer.data), buffer_peak_bytes=self.buffer.peak_bytes, stream_buffer_accepted_bytes=self.buffer.accepted_bytes, stream_buffer_discarded_bytes=self.buffer.discarded_bytes, stream_buffer_unaccepted_bytes=self.buffer.unaccepted_bytes, stream_output_discarded_bytes=self.buffer.discarded_bytes + self.buffer.unaccepted_bytes)
        with self.network._lock:
            facts['active_sockets'] = len(self.network._sockets)
        facts['reader_state'] = self.reader_state
        return facts

    def _report(self, event):
        self.stages.append(event)
        stage = next((x for x in ('bootstrap', 'gateway', 'center', 'parent') if event.startswith(x)), 'receiver')
        self.diagnostics.event(stage, event)

    def _emit(self, data):
        atomic_unit = 188 if len(data) % 188 == 0 else 1
        self.buffer.put(data, atomic_unit=atomic_unit)

    def open(self):
        thread = _sg_stream_threading.Thread(target=self._run, name='soop-grid-receiver', daemon=True)
        start_error = None
        phase = 'diagnostics'
        with self._close_lock:
            if self.thread is not None or self.closed:
                start_error = _sg_stream_StreamError('Grid reader already opened or closed')
            else:
                try:
                    self.diagnostics.start()
                    phase = 'receiver'
                    thread.start()
                except BaseException as error:
                    start_error = (phase, error)
                else:
                    self.thread = thread
        if start_error is not None:
            if isinstance(start_error, tuple):
                phase, error = start_error
            else:
                error = start_error
            if phase == 'diagnostics':
                self.close()
                raise error
            if not isinstance(error, (KeyboardInterrupt, SystemExit)):
                self.failure_code = 'receiver_thread_start_failed'
                self.diagnostics.fail(_sg_stream_GridError(self.failure_code))
            self.close()
            if isinstance(error, (KeyboardInterrupt, SystemExit)):
                raise
            if isinstance(error, _sg_stream_StreamError):
                raise error
            raise _sg_stream_StreamError('SOOP Grid: receiver_thread_start_failed') from None
        try:
            self.buffer.wait_ready()
            if self._closing or self.closed:
                raise _sg_stream_StreamError('Grid reader closed while opening')
        except BaseException as error:
            cancelled = isinstance(error, KeyboardInterrupt) or self._closing or self.closed
            if not cancelled and (not self.failure_code):
                self.diagnostics.fail(_sg_stream_GridError('reader_timeout'))
            self.close()
            if self.failure_code and isinstance(error, Exception):
                error.grid_error_code = self.failure_code
            raise
        return self

    def _run(self):
        error = None
        try:
            self.runner(self.stream.config, self.network, self._emit, self._report, self.stats)
            self.diagnostics.complete(self.stats.get('stop_reason', 'receiver_completed_unknown'))
        except BaseException as exc:
            code = _sg_stream_safe_error(exc)
            self.failure_code = code
            reason = 'center_rediscovery_failed' if self.stats.get('center_rediscovery_failed') and _sg_stream_stop_reason(exc) != 'authentication_denied' else None
            self.diagnostics.fail(exc, reason)
            if not self._closing:
                error = _sg_stream_StreamError('SOOP Grid: ' + code)
                _sg_stream__log.error('Native Grid receiver stopped: %s (%s)', code, self.diagnostics.reason)
        finally:
            self.network.close()
            self.buffer.finish(error)
            self.diagnostics.event(event='worker_finished')
            self.diagnostics.summary()

    def readable(self):
        return not self.closed

    def read(self, size=-1):
        if self.closed or self._closing:
            return b''
        try:
            result = self.buffer.read(size)
            if result:
                self.reader_state = 'streaming'
                self.stats['stream_reader_bytes'] = self.stats.get('stream_reader_bytes', 0) + len(result)
            elif size != 0:
                self.reader_state = 'eof'
                self.stats['reader_eof_observed'] = 1
                self.diagnostics.event('reader', 'reader_eof')
            return result
        except _sg_stream_StreamError as exc:
            self.reader_state = 'error'
            if not self.failure_code:
                self.diagnostics.fail(_sg_stream_GridError('reader_timeout'))
